const b = $input.first().json.body || {};
if (!b.runId) throw new Error('Missing runId in the request body');
return [{ json: {
  runId: b.runId, ownerId: b.ownerId ?? null, jobId: b.jobId ?? null, agentId: b.agentId ?? null,
  ...(b.payload || {}),
} }];

const env = $('Read envelope').first().json;
const cfg = $('Config').first().json.cfg;
const bids = $input.all().map((i) => i.json).filter((b) => b.id);
if (!Number.isFinite(Number(env.maxPrice))) throw new Error('payload.maxPrice is required');
const postedAt = bids[0] && bids[0].posted_at ? new Date(bids[0].posted_at) : null;
const waited = postedAt ? (Date.now() - postedAt) / 60000 : 0;

// Paper III.d: wait for 3 VALID offers (not held, not flagged) or the window
const valid = bids.filter((b) => Number(b.fraud_score || 0) < 70 && b.price_check !== 'held');
if (bids.length === 0) return [{ json: { decision: 'wait', reason: 'No live bids yet' } }];
if (valid.length < 3 && waited < cfg.windowMinutes) {
  return [{ json: { decision: 'wait',
    reason: `${valid.length} of 3 valid offers after ${Math.floor(waited)} of ${cfg.windowMinutes} minutes` } }];
}

const prices = bids.map((b) => Number(b.price)).sort((a, b) => a - b);
const mid = Math.floor(prices.length / 2);
const bidMedian = prices.length % 2 ? prices[mid] : (prices[mid - 1] + prices[mid]) / 2;
const ref = Number(bids.find((b) => b.reference_median)?.reference_median) || bidMedian;

const eligible = bids.filter((b) => Number(b.fraud_score || 0) < 70 && b.price_check !== 'held');
const scored = eligible.map((b) => {
  const price = Number(b.price);
  let priceScore = (ref - price) / ref;             // cheaper than reference = better
  if (price < 0.5 * ref) priceScore = -0.5;          // suspiciously cheap = worse
  const rep = Math.min(Number(b.settled_jobs || 0), 10) / 10;
  const pass = Number(b.first_try_pass_rate ?? 50) / 100;
  const eta = 1 / Math.max(Number(b.eta_days || 3), 0.5);
  const score = 0.4 * priceScore + 0.3 * rep + 0.2 * pass + 0.1 * eta;
  return { id: b.id, seller: b.display_name, kind: b.kind, price, eta_days: Number(b.eta_days || 0),
           settled_jobs: Number(b.settled_jobs || 0), pass_rate: b.first_try_pass_rate,
           rounds: Number(b.rounds || 0), last_sender: b.last_sender,
           note: String(b.note || '').slice(0, 400), score: Math.round(score * 1000) / 1000 };
}).sort((a, b) => b.score - a.score).slice(0, 5);

if (scored.length === 0) return [{ json: { decision: 'wait', reason: 'Every bid is held or flagged' } }];
return [{ json: { decision: 'think', shortlist: scored, ids: scored.map((b) => b.id),
  reference: ref, maxPrice: Number(env.maxPrice), title: bids[0].title,
  description: bids[0].description, liveCount: bids.length } }];

